effect.shader:
vec3 colorBurn(vec3 base, vec3 blend) {
vec3 safeBlend = max(blend, vec3(0.000001));
return 1.0 - min(vec3(1.0), (1.0 - base) / safeBlend);
}
vec3 colorDodge(vec3 base, vec3 blend) {
vec3 safeInvBlend = max(1.0 - blend, vec3(0.000001));
return min(vec3(1.0), base / safeInvBlend);
}
void main() {
vec4 topSample = texture2DCv(inputImg.texture, acScreenNorm);
vec4 baseSample = texture2DCv(comp.texture, acScreenNorm);
vec3 top = clamp(topSample.rgb, 0.0, 1.0);
vec3 base = clamp(baseSample.rgb, 0.0, 1.0);
vec3 lowBranch = colorBurn(base, clamp(2.0 * top, 0.0, 1.0));
vec3 highBranch = colorDodge(base, clamp(2.0 * (top - 0.5), 0.0, 1.0));
vec3 vivid = mix(lowBranch, highBranch, step(vec3(0.5), top));
vec3 hardMix = step(vec3(0.5), vivid);
gl_FragColor = vec4(hardMix * topSample.a, topSample.a);
}
